"use client";

import { motion, useReducedMotion } from "framer-motion";

const SakuraPetals = () => {
  const reducedMotion = useReducedMotion();
  const petals = Array.from({ length: 14 }, (_, i) => ({
    left: `${(i * 7 + 5) % 100}%`,
    size: 8 + (i % 4) * 3,
    delay: (i % 7) * 1.2,
    duration: 14 + (i % 5) * 4,
    drift: ((i % 3) - 1) * 40,
  }));

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: 0,
      }}
    >
      {petals.map((petal, index) => (
        <motion.span
          key={index}
          style={{
            width: `${petal.size}px`,
            height: `${petal.size}px`,
            borderRadius: "50% 0 50% 50%",
            background: "var(--tl-petal)",
            opacity: 0.5,
            position: "absolute",
            top: reducedMotion ? `${(index * 11) % 90}%` : "-5%",
            left: petal.left,
          }}
          animate={reducedMotion ? undefined : { y: ["0vh", "110vh"], x: [0, petal.drift, 0], rotate: [0, 180, 360] }}
          transition={reducedMotion ? undefined : { duration: petal.duration, delay: petal.delay, repeat: Infinity, ease: "linear" }}
        />
      ))}
    </div>
  );
};

export default SakuraPetals;
